/**
 * GitHub webhook channel pack for agent-serve (Eve-compatible dispatch).
 *
 * ```ts
 * import { defaultGitHubAuth, githubChannel } from "@grok/agent-sdk/channels/github";
 *
 * export default githubChannel({
 *   botName: "my-agent",
 *   // Reuses `agent-sdk login` for events, ctx.github, ctx.host.github, and gh.
 *   cursorAccount: { repos: ["owner/repo"] },
 *   onComment: (ctx, comment) => ({ auth: defaultGitHubAuth(ctx) }),
 *   onPullRequest: (ctx, pr) =>
 *     pr.action === "opened" ? { auth: defaultGitHubAuth(ctx) } : null,
 *   onCheckSuite: (ctx, suite) =>
 *     suite.conclusion === "failure" && suite.pullRequests.length > 0
 *       ? { auth: defaultGitHubAuth(ctx) }
 *       : null,
 *   // Legacy commit statuses
 *   onStatus: (ctx, status) =>
 *     status.state === "failure"
 *       ? {
 *           task: () =>
 *             ctx.github.createStatus({
 *               sha: status.sha,
 *               state: "pending",
 *               context: "agent/triage",
 *             }),
 *         }
 *       : null,
 *   // Catch-all for other webhook events
 *   onEvent: (ctx, event) =>
 *     event.eventName === "label" ? { auth: defaultGitHubAuth(ctx) } : null,
 * });
 * ```
 *
 * Inbound hooks receive `ctx.github` (`getOctokit`, `request`, `createStatus`)
 * and `ctx.thread` (`post`, `react`). Prefer typed Octokit methods via
 * `await ctx.github.getOctokit()` for new code. Without `onPullRequest`,
 * agent-serve keeps a backward-compatible default gate (opened / reopened /
 * synchronize / ready_for_review). Eve itself is opt-in for that hook.
 */
